import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.junit.Test;

public class CustomerMasterTest {
    @Test
    public void testCustomerMasterCRUD() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/auth/login");
        driver.findElement(By.xpath("//button[contains(text(),'Master Data')]")).click();
        driver.findElement(By.xpath("//a[contains(text(),'Customer Master')]")).click();
        driver.findElement(By.xpath("//button[contains(text(),'Add Customer')]")).click();
        driver.findElement(By.id("partyCode")).sendKeys("CUST_SEL_01");
        driver.findElement(By.id("customerName")).sendKeys("Selenium Test Customer");
        driver.findElement(By.id("country")).sendKeys("India");
        driver.findElement(By.id("state")).sendKeys("Maharashtra");
        driver.findElement(By.id("region")).sendKeys("West");
        driver.findElement(By.xpath("//button[contains(text(),'Submit')]")).click();
        driver.quit();
    }
}
